CREATE DEFINER=`root`@`localhost` PROCEDURE `BuscarRegistroPorMatricula` (IN `matricula_search` VARCHAR(10))   BEGIN
    SELECT id_registro, hora_entrada, hora_salida, matricula, id_servicio
    FROM registro
    WHERE matricula LIKE CONCAT('%', matricula_search, '%')
    AND status = 0;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `CheckUserExists` (IN `p_user` VARCHAR(50), OUT `p_user_count` INT)   BEGIN
    SELECT COUNT(*) INTO p_user_count FROM user WHERE user = p_user;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `FilterRecords` (IN `p_startTime` DATETIME, IN `p_endTime` DATETIME)   BEGIN
    SELECT r.id_registro, r.hora_entrada, r.hora_salida, r.matricula, r.nombre, e.nombre_especialidad, s.nombre_servicio
    FROM registro r
    INNER JOIN especialidades e ON r.id_especialidad = e.id_especialidad
    INNER JOIN servicios s ON r.id_servicio = s.id_servicio
    WHERE r.status = 1 AND r.hora_entrada >= p_startTime AND r.hora_salida <= p_endTime;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `GetPasswordHash` (IN `p_user` VARCHAR(50), OUT `p_password_hash` VARCHAR(60))   BEGIN
    SELECT password_user INTO p_password_hash FROM user WHERE user = p_user LIMIT 1;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `GetRecords` (IN `p_startTime` DATETIME, IN `p_endTime` DATETIME, IN `p_searchTerm` VARCHAR(100))   BEGIN
    SELECT r.id_registro, r.hora_entrada, r.hora_salida, r.matricula, r.nombre, e.nombre_especialidad, s.nombre_servicio
    FROM registro r
    INNER JOIN especialidades e ON r.id_especialidad = e.id_especialidad
    INNER JOIN servicios s ON r.id_servicio = s.id_servicio
    WHERE r.status = 1 AND (
        (p_startTime IS NULL OR r.hora_entrada >= p_startTime) AND
        (p_endTime IS NULL OR r.hora_salida <= p_endTime) AND
        (p_searchTerm IS NULL OR 
         r.matricula LIKE CONCAT('%', p_searchTerm, '%') OR 
         r.nombre LIKE CONCAT('%', p_searchTerm, '%') OR
         e.nombre_especialidad LIKE CONCAT('%', p_searchTerm, '%') OR
         s.nombre_servicio LIKE CONCAT('%', p_searchTerm, '%') OR
         r.hora_entrada LIKE CONCAT('%', p_searchTerm, '%') OR
         r.hora_salida LIKE CONCAT('%', p_searchTerm, '%'))
    );
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `insertar_registro` (IN `_matricula` VARCHAR(10), IN `_nombre` VARCHAR(200), IN `_id_carrera` INT, IN `_id_especialidad` INT, IN `_id_servicio` INT, IN `_hora_entrada` DATETIME)   BEGIN
    DECLARE _id_registro INT;

    VALUES (_matricula, _nombre, _id_carrera, _id_especialidad, _id_servicio, _hora_entrada);

    SET _id_registro = LAST_INSERT_ID();
    
    SELECT _id_registro AS id_registro;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `insertar_solicitud_servicio` (IN `matricula_param` VARCHAR(10), IN `nombre_param` VARCHAR(255), IN `id_carrera_param` INT, IN `id_especialidad_param` INT, IN `id_servicio_param` INT, IN `hora_entrada_param` DATETIME)   BEGIN
    DECLARE existe_registro INT;

    -- Verificar si hay un registro con la misma matrícula y estado en cero
    SELECT COUNT(*) INTO existe_registro
    FROM registro
    WHERE matricula = matricula_param AND status = 0;

    IF existe_registro > 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Ya existe un registro con la misma matrícula y estado en cero';
    ELSE
        -- Insertar el nuevo registro
        VALUES (matricula_param, nombre_param, id_carrera_param, id_especialidad_param, id_servicio_param, hora_entrada_param);
    END IF;
END$$

