CREATE DEFINER=`root`@`localhost` PROCEDURE `RegistrarSalida` (IN `registroId` INT)   BEGIN
    DECLARE horaSalida TIMESTAMP;
    SET horaSalida = NOW();

    UPDATE registro SET hora_salida = horaSalida, status = 1 WHERE id_registro = registroId;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `SearchRecords` (IN `p_searchTerm` VARCHAR(255))   BEGIN
    SET @searchTerm = CONCAT('%', p_searchTerm, '%');

    SELECT r.id_registro, r.hora_entrada, r.hora_salida, r.matricula, r.nombre, e.nombre_especialidad, s.nombre_servicio
    FROM registro r
    INNER JOIN especialidades e ON r.id_especialidad = e.id_especialidad
    INNER JOIN servicios s ON r.id_servicio = s.id_servicio
    WHERE r.status = 1 AND (r.matricula LIKE @searchTerm OR r.nombre LIKE @searchTerm 
    OR e.nombre_especialidad LIKE @searchTerm OR s.nombre_servicio LIKE @searchTerm 
    OR r.hora_entrada LIKE @searchTerm OR r.hora_salida LIKE @searchTerm);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `VerificarCredenciales` (IN `username` VARCHAR(50), IN `password` VARCHAR(60))   BEGIN
    DECLARE hashedPassword VARCHAR(60);
    SELECT password_user INTO hashedPassword FROM user WHERE user = username;
    
    IF hashedPassword IS NOT NULL AND hashedPassword <> '' AND password_verify(password, hashedPassword) THEN
        SELECT 1 AS valid;
    ELSE
        SELECT 0 AS valid;
    END IF;
END$$

